<?php
declare(strict_types=1);
require dirname(__DIR__) . '/app/bootstrap.php'; require_admin();
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT) ?: 0;
$property=[];
if($id){$stmt=db()->prepare('SELECT * FROM properties WHERE id=?');$stmt->execute([$id]);$property=$stmt->fetch() ?: [];if(!$property){http_response_code(404);exit('Property not found.');}}
$defaults=['title'=>'','slug'=>'','property_type'=>'house','status'=>'rented','address_line1'=>'','address_line2'=>'','city'=>'Evansville','state'=>'IN','postal_code'=>'','latitude'=>'','longitude'=>'','bedrooms'=>'','bathrooms'=>'','square_feet'=>'','units'=>'','year_built'=>'','purchase_price'=>'','purchase_date'=>'','zillow_value'=>'','zillow_checked_at'=>'','rent_amount'=>'','nightly_rate'=>'','sale_price'=>'','available_date'=>'','description'=>'','private_notes'=>'','is_visible'=>1];
$property=array_merge($defaults,$property);$error='';
function nullable_number(string $key): ?string {$v=trim((string)($_POST[$key]??''));return $v===''?null:$v;}
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$types=['house','apartment','airbnb'];$statuses=['rented','available','coming_soon','sold'];
 $title=trim((string)($_POST['title']??''));$slug=preg_replace('/[^a-z0-9]+/','-',strtolower(trim((string)($_POST['slug']?:$title))));$slug=trim((string)$slug,'-');
 if(!$title||!in_array($_POST['property_type']??'',$types,true)||!in_array($_POST['status']??'',$statuses,true)||!is_numeric($_POST['latitude']??'')||!is_numeric($_POST['longitude']??'')) $error='Title, type, status, latitude, and longitude are required.';
 else {
  $data=[$slug,$title,$_POST['property_type'],$_POST['status'],trim($_POST['address_line1']),trim($_POST['address_line2']),trim($_POST['city']),strtoupper(trim($_POST['state'])),trim($_POST['postal_code']),$_POST['latitude'],$_POST['longitude'],nullable_number('bedrooms'),nullable_number('bathrooms'),nullable_number('square_feet'),nullable_number('units'),nullable_number('year_built'),nullable_number('purchase_price'),$_POST['purchase_date']?:null,nullable_number('zillow_value'),$_POST['zillow_checked_at']?:null,nullable_number('rent_amount'),nullable_number('nightly_rate'),nullable_number('sale_price'),$_POST['available_date']?:null,trim($_POST['description']),trim($_POST['private_notes']),isset($_POST['is_visible'])?1:0];
  $oldZillow=$id?($property['zillow_value']?:null):null;
  if($id){$sql='UPDATE properties SET slug=?,title=?,property_type=?,status=?,address_line1=?,address_line2=?,city=?,state=?,postal_code=?,latitude=?,longitude=?,bedrooms=?,bathrooms=?,square_feet=?,units=?,year_built=?,purchase_price=?,purchase_date=?,zillow_value=?,zillow_checked_at=?,rent_amount=?,nightly_rate=?,sale_price=?,available_date=?,description=?,private_notes=?,is_visible=? WHERE id=?';$data[]=$id;db()->prepare($sql)->execute($data);}
  else{$sql='INSERT INTO properties (slug,title,property_type,status,address_line1,address_line2,city,state,postal_code,latitude,longitude,bedrooms,bathrooms,square_feet,units,year_built,purchase_price,purchase_date,zillow_value,zillow_checked_at,rent_amount,nightly_rate,sale_price,available_date,description,private_notes,is_visible) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)';db()->prepare($sql)->execute($data);$id=(int)db()->lastInsertId();}
  $newZillow=nullable_number('zillow_value');if($newZillow!==null && (string)$oldZillow!==(string)$newZillow){db()->prepare("INSERT INTO property_value_history(property_id,value_amount,value_source,valued_on) VALUES (?,?,'zillow',?)")->execute([$id,$newZillow,$_POST['zillow_checked_at']?:date('Y-m-d')]);}
  header('Location: '.base_url('admin/property.php?id='.$id.'&saved=1'));exit;
 }
 $property=array_merge($property,$_POST);
}
$photos=[];if($id){$s=db()->prepare('SELECT * FROM property_photos WHERE property_id=? ORDER BY sort_order,id');$s->execute([$id]);$photos=$s->fetchAll();}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($id?'Edit property':'Add property')?> | Admin</title><link rel="stylesheet" href="<?=e(base_url('assets/css/admin.css?v=20260910-2'))?>"></head><body><header class="admin-header"><img src="<?=e(base_url('assets/img/mavrei-logo-transparent.png?v=20260910-3'))?>" alt="Maverick"><nav><a href="<?=e(base_url('admin/'))?>">Properties</a><a href="<?=e(base_url())?>">View map</a></nav></header><main class="admin-wrap narrow"><div class="admin-title"><div><p class="eyebrow">Portfolio administration</p><h1><?=e($id?'Edit property':'Add property')?></h1></div></div><?php if(isset($_GET['saved'])):?><p class="alert success">Property saved.</p><?php endif;?><?php if($error):?><p class="alert error"><?=e($error)?></p><?php endif;?><form class="property-form" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><section><h2>Identity and map</h2><div class="form-grid"><label class="span-2">Property name<input name="title" value="<?=e($property['title'])?>" required></label><label class="span-2">URL slug<input name="slug" value="<?=e($property['slug'])?>"></label><label>Property type<select name="property_type"><?php foreach(['house'=>'House','apartment'=>'Apartment','airbnb'=>'Airbnb'] as $v=>$l):?><option value="<?=$v?>" <?=$property['property_type']===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><label>Status<select name="status"><?php foreach(['rented'=>'Rented','available'=>'Available','coming_soon'=>'Coming Soon','sold'=>'Sold'] as $v=>$l):?><option value="<?=$v?>" <?=$property['status']===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><label class="span-2">Address<input name="address_line1" value="<?=e($property['address_line1'])?>" required></label><label>City<input name="city" value="<?=e($property['city'])?>" required></label><label>State<input name="state" maxlength="2" value="<?=e($property['state'])?>" required></label><label>ZIP<input name="postal_code" value="<?=e($property['postal_code'])?>" required></label><label>Latitude<input name="latitude" inputmode="decimal" value="<?=e((string)$property['latitude'])?>" required></label><label>Longitude<input name="longitude" inputmode="decimal" value="<?=e((string)$property['longitude'])?>" required></label><label class="check"><input type="checkbox" name="is_visible" <?=$property['is_visible']?'checked':''?>> Show on public map</label></div></section><section><h2>Property facts</h2><div class="form-grid"><label>Bedrooms<input type="number" step="0.5" name="bedrooms" value="<?=e((string)$property['bedrooms'])?>"></label><label>Bathrooms<input type="number" step="0.5" name="bathrooms" value="<?=e((string)$property['bathrooms'])?>"></label><label>Square feet<input type="number" name="square_feet" value="<?=e((string)$property['square_feet'])?>"></label><label>Units<input type="number" name="units" value="<?=e((string)$property['units'])?>"></label><label>Year built<input type="number" name="year_built" value="<?=e((string)$property['year_built'])?>"></label><label>Available date<input type="date" name="available_date" value="<?=e((string)$property['available_date'])?>"></label></div></section><section><h2>Financial tracking</h2><div class="form-grid"><label>Monthly rent<input type="number" step="0.01" name="rent_amount" value="<?=e((string)$property['rent_amount'])?>"></label><label>Airbnb nightly rate<input type="number" step="0.01" name="nightly_rate" value="<?=e((string)$property['nightly_rate'])?>"></label><label>Purchase price<input type="number" step="0.01" name="purchase_price" value="<?=e((string)$property['purchase_price'])?>"></label><label>Purchase date<input type="date" name="purchase_date" value="<?=e((string)$property['purchase_date'])?>"></label><label>Sale price<input type="number" step="0.01" name="sale_price" value="<?=e((string)$property['sale_price'])?>"></label><label>Zillow value<input type="number" step="0.01" name="zillow_value" value="<?=e((string)$property['zillow_value'])?>"></label><label>Zillow checked date<input type="date" name="zillow_checked_at" value="<?=e((string)$property['zillow_checked_at'])?>"></label></div></section><section><h2>Details and notes</h2><label>Description<textarea name="description" rows="5"><?=e($property['description'])?></textarea></label><label>Private notes<textarea name="private_notes" rows="5"><?=e($property['private_notes'])?></textarea></label></section><button class="button" type="submit">Save property</button></form><?php if($photos):?><section class="admin-photos"><h2>Imported photos (<?=count($photos)?>)</h2><div><?php foreach($photos as $ph):?><img src="<?=e(base_url($ph['file_path']))?>" alt="" loading="lazy"><?php endforeach;?></div></section><?php endif;?></main></body></html>

